// FUNCTION: BFME2 0x004959FF size=44 name=?onObjectCreated@DemoTrapUpdate@@UAEXXZ evidence=N:ledger
void DemoTrapUpdate::onObjectCreated()
{
	const DemoTrapUpdateModuleData *data = (const DemoTrapUpdateModuleData *)getModuleData();
	getObject()->setWeaponSetFlag((WeaponSetType)0);
	if (data->m_defaultProximityMode)
		getObject()->setWeaponLock((WeaponSlotType)data->m_proximityModeWeaponSlot, (WeaponLockType)1);
	else
		getObject()->setWeaponLock((WeaponSlotType)data->m_manualModeWeaponSlot, (WeaponLockType)1);
}


