void DemoTrapUpdate::rva00495A2B()
{
	Object *trap = getObject();
	if (!trap->testStatus((ObjectStatusTypes)2) && !trap->testStatus((ObjectStatusTypes)0x13))
		TheWeaponStore->createAndFireTempWeapon(((const DemoTrapUpdateModuleData *)getModuleData())->m_detonationWeapon, trap, trap->getPosition());
	trap->kill(DAMAGE_UNRESISTABLE, (DeathType)0);
	m_detonated = true;
}

